// Auto-generated runtime entry point for chaos-il2cpp AOT output.
// Supports six modes:
//   (no args)                        - Fact mode: run all methods, print Passed N/M
//   N                                - Legacy single-entry mode (backward compat)
//   --benchmark N [I]                - Benchmark mode: run method N for I iterations, print JSON timing
//   --hotupdate                      - HotUpdate mode: run patch lifecycle, print JSON results
//   --hotupdate-and-benchmark N [I]  - Apply hotpatch then benchmark method N, print combined JSON
//   --patch-bench N [I]              - Apply hotpatch then benchmark method N (skip all-methods loop)
#include <cstdint>
#include <cstdlib>
#include <cstdio>
#include <cstring>
#include <chrono>
#include <setjmp.h>
#include "codegen_bridge.h"
#include "runtime_abi.h"
#include "runtime_core.h"
#include "exception_helpers.h"
#include "patch_loader.h"
#include "hotpatch_table.h"
#include "chaos/profile.h"

// SetExceptionFallback is declared at global scope in exception_helpers.h.
// Forward-declare here so this file compiles independently.
extern "C" void SetExceptionFallback(void (*fn)());

extern "C" std::int32_t RunNativeAot(std::int32_t);
extern "C" std::int32_t RunNativeAotAll();
extern "C" std::int32_t RunNativeAotBench(std::int32_t);
extern "C" double BenchmarkMethod(int, int);

// ── Microbenchmark mode (--microbench) ──────────────────────────────────
// Forward declarations.
int RunMicrobench() noexcept;
void DumpProfileResults() noexcept;

// Generated by pipeline: defines kPatchData[], kPatchDataSize, kPatchDataHostClassName
// See _generate_patch_data() in pipeline_native_aot_runner.py
extern const uint8_t kPatchData[];
extern const size_t kPatchDataSize;
extern const char* const kPatchDataHostClassName;

// Codegen-emitted registration structs (from native-aot.generated.cpp)
extern "C" const CodeRegistrationV0 chaos_codegen_code_registration;
extern "C" const MetadataRegistrationV0 chaos_codegen_metadata_registration;
extern "C" const CodegenRegistrationOptionsV0 chaos_codegen_options;

// kAotMethodCount defined in codegen-emitted code (native-aot.generated.cpp)
extern "C" const int kAotMethodCount;

enum class RunMode { Fact, Benchmark, HotUpdate, HotUpdateAndBenchmark, PatchAndBenchmark };

// ── Exception fallback for verification mode ─────────────────────────────
// When conversion functions (e.g., chaos_convert_tochar_int32) call
// RaiseManagedException() in an uninitialized runtime, the fallback redirects
// to longjmp so the verification harness can catch the failure instead of abort().
// Framework exception types (OverflowException, InvalidCastException) are not
// registered in per-family builds, so ResolveTypeByName() would fail anyway.
static thread_local jmp_buf s_verify_buf;

static void exception_fallback() {
    longjmp(s_verify_buf, 1);
}

// ── Shared helper: apply hotpatch and print diagnostic ─────────────────────
// Returns the patch context, or nullptr if no patch data is available.
// Three CLI modes (HotUpdate, HotUpdateAndBenchmark, PatchAndBenchmark) share
// the same ApplyPatchFromMemory call — this helper eliminates the duplication.
static chaos::il2cpp::runtime_core::PatchContext* ApplyHotpatchIfAvailable() {
    if (kPatchDataSize > 0u) {
        auto* patch_ctx = chaos::il2cpp::runtime_core::ApplyPatchFromMemory(
            kPatchData, kPatchDataSize, kPatchDataHostClassName);
        if (patch_ctx == nullptr) {
            std::fprintf(stderr, "WARN: ApplyPatchFromMemory returned null (no patches applied)\n");
        } else {
            std::fprintf(stderr, "INFO: Applied patches to %u methods\n",
                         static_cast<unsigned>(patch_ctx->method_count));
        }
        return patch_ctx;
    }
    return nullptr;
}

int main(int argc, char** argv) {
    auto* bridge = chaos_codegen_get_bridge_v0();
    if (!bridge) return -1;
    bridge->register_codegen(
        &chaos_codegen_code_registration,
        &chaos_codegen_metadata_registration,
        &chaos_codegen_options);
    bridge->bootstrap_runtime();

    // Set TLS to non-null sentinels so RaiseManagedException gets past its
    // first guard (runtime == nullptr / thread == nullptr check).  No
    // dereference of RuntimeState or ThreadState occurs because
    // ResolveTypeByName returns 0 (framework types not registered in
    // per-family builds), which now throws chaos_managed_exception{0}
    // instead of calling the exception fallback.
    //
    // RuntimeState and ThreadState are opaque types (only forward-declared
    // in runtime_abi.h), so genuine instances cannot be created here.
    // Sentinels are safe because the codegen exception path never
    // dereferences these pointers when type resolution fails.
    chaos::il2cpp::runtime_core::SetCurrentRuntimeState(
        reinterpret_cast<RuntimeState*>(static_cast<uintptr_t>(1)));
    chaos::il2cpp::runtime_core::SetCurrentThreadState(
        reinterpret_cast<ThreadState*>(static_cast<uintptr_t>(1)));

    // Install exception fallback: RaiseManagedException → longjmp recovery.
    // Retained as safety net: if TLS is ever null or an unexpected code path
    // reaches the abort(), the fallback still provides controlled recovery.
    SetExceptionFallback(&exception_fallback);

    RunMode mode = RunMode::Fact;
    int entry_index = 0;
    int iterations = 10000;

    // Simple argv parsing (self-contained, no getopt dependency)
    if (argc >= 3 && std::strcmp(argv[1], "--benchmark") == 0) {
        mode = RunMode::Benchmark;
        entry_index = std::atoi(argv[2]);
        if (argc >= 4) iterations = std::atoi(argv[3]);
    } else if (argc >= 2 && std::strcmp(argv[1], "--hotupdate") == 0) {
        mode = RunMode::HotUpdate;
    } else if (argc >= 3 && std::strcmp(argv[1], "--hotupdate-and-benchmark") == 0) {
        mode = RunMode::HotUpdateAndBenchmark;
        entry_index = std::atoi(argv[2]);
        if (argc >= 4) iterations = std::atoi(argv[3]);
    } else if (argc >= 3 && std::strcmp(argv[1], "--patch-bench") == 0) {
        mode = RunMode::PatchAndBenchmark;
        entry_index = std::atoi(argv[2]);
        if (argc >= 4) iterations = std::atoi(argv[3]);
    } else if (argc >= 2 && std::strcmp(argv[1], "--fact-profile") == 0) {
        mode = RunMode::Fact;
    } else if (argc >= 2 && std::strcmp(argv[1], "--microbench") == 0) {
        return RunMicrobench();
    } else if (argc >= 2) {
        entry_index = std::atoi(argv[1]);  // backward compat: numeric entry index
    }

    switch (mode) {
    case RunMode::Fact: {
        int result = 0;
        if (setjmp(s_verify_buf) == 0) {
            try {
                result = RunNativeAotAll();
            } catch (...) {
                longjmp(s_verify_buf, 1);
            }
        }
        int failed_count = 0;
        int tmp = result;
        while (tmp) { failed_count += tmp & 1; tmp >>= 1; }
        int passed_count = kAotMethodCount - failed_count;
        printf("Passed: %d/%d\n", passed_count, kAotMethodCount);
        // Dump profile scope data if --fact-profile was requested
        DumpProfileResults();
        std::fflush(stdout);
        return result;
    }
    case RunMode::Benchmark: {
        // Benchmark via direct kAotMethods[] call, no dispatch/hotpatch overhead
        double elapsed_ms = -1.0;
        if (setjmp(s_verify_buf) == 0) {
            try {
                elapsed_ms = BenchmarkMethod(entry_index, iterations);
            } catch (...) {
                longjmp(s_verify_buf, 1);
            }
        }
        if (elapsed_ms < 0.0) {
            printf("{\"error\":\"invalid method index %d\"}\n", entry_index);
            std::fflush(stdout);
            return -1;
        }
        double ops_per_sec = iterations / (elapsed_ms / 1000.0);

        printf("{\"elapsedMilliseconds\":%.3f,\"calibratedMs\":%.3f,\"calOverheadMs\":0.000,"
               "\"opsPerSecond\":%.1f,\"iterations\":%d,\"methodIndex\":%d}\n",
               elapsed_ms, elapsed_ms, ops_per_sec, iterations, entry_index);
        std::fflush(stdout);
        return 0;
    }
    case RunMode::HotUpdate: {
        ApplyHotpatchIfAvailable();
        int result = 0;
        if (setjmp(s_verify_buf) == 0) {
            try {
                result = RunNativeAotAll();
            } catch (...) {
                longjmp(s_verify_buf, 1);
            }
        }
        int failed_count = 0;
        int tmp2 = result;
        while (tmp2) { failed_count += tmp2 & 1; tmp2 >>= 1; }
        int passed_count = kAotMethodCount - failed_count;
        printf("{\"passedMethods\":%d,\"failedMethods\":%d,\"totalMethods\":%d}\n",
               passed_count, failed_count, kAotMethodCount);
        std::fflush(stdout);
        return result;
    }
    case RunMode::HotUpdateAndBenchmark: {
        ApplyHotpatchIfAvailable();
        // Run all methods (now routed through dispatch table, patched methods → interpreter)
        int hot_result = 0;
        if (setjmp(s_verify_buf) == 0) {
            try {
                hot_result = RunNativeAotAll();
            } catch (...) {
                longjmp(s_verify_buf, 1);
            }
        }
        // Then benchmark the specified method (now running through interpreter when patched)
        auto start = std::chrono::steady_clock::now();
        for (int i = 0; i < iterations; i++) {
            if (setjmp(s_verify_buf) == 0) {
                try {
                    RunNativeAot(entry_index);
                } catch (...) {
                    longjmp(s_verify_buf, 1);
                }
            }
        }
        auto end = std::chrono::steady_clock::now();
        auto elapsed_ms = std::chrono::duration<double, std::milli>(end - start).count();
        double ns_per_op = (elapsed_ms * 1e6) / iterations;
        printf("{\"postPatchNsPerOp\":%.1f,\"elapsedMilliseconds\":%.3f,\"iterations\":%d,\"methodIndex\":%d,\"hotResult\":%d}\n",
               ns_per_op, elapsed_ms, iterations, entry_index, hot_result);
        std::fflush(stdout);
        return 0;
    }
    case RunMode::PatchAndBenchmark: {
        ApplyHotpatchIfAvailable();
        // Skip RunNativeAotAll — go straight to benchmarking the target method.
        // Uses RunNativeAotBench (no setjmp, inline slot access) for max perf.
        auto start = std::chrono::steady_clock::now();
        for (int i = 0; i < iterations; i++) {
            if (setjmp(s_verify_buf) == 0) {
                try {
                    RunNativeAotBench(entry_index);
                } catch (...) {
                    longjmp(s_verify_buf, 1);
                }
            }
        }
        auto end = std::chrono::steady_clock::now();
        auto elapsed_ms = std::chrono::duration<double, std::milli>(end - start).count();
        double ns_per_op = (elapsed_ms * 1e6) / iterations;
        printf("{\"postPatchNsPerOp\":%.1f,\"elapsedMilliseconds\":%.3f,\"iterations\":%d,\"methodIndex\":%d}\n",
               ns_per_op, elapsed_ms, iterations, entry_index);
        std::fflush(stdout);
        return 0;
    }
    }
}

// ══════════════════════════════════════════════════════════════════════════
// ── Microbenchmark Implementation ─────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════

#include "fast_dispatch.h"
#include "fast_frame_pool.h"
#include "interpreter_vm.h"
#include <chaos/profile.h>

namespace ic = chaos::il2cpp::interpreter;
namespace rc = chaos::il2cpp::runtime_core;
namespace cm = chaos::il2cpp::common;

static constexpr int kMBenchIters = 200000;

// ── RDTSC-to-ns through calibrated QPC ─────────────────────────────────
static int64_t NowNs() noexcept {
    static auto epoch = std::chrono::steady_clock::now();
    auto now = std::chrono::steady_clock::now();
    return std::chrono::duration_cast<std::chrono::nanoseconds>(now - epoch).count();
}

// ── Dump accumulated PROFILE_SCOPE data (after fact tests) ──────────────
void DumpProfileResults() noexcept {
#if CHAOS_IL2CPP_PROFILE_ENABLED
    if (!cm::g_profile_calibrated) cm::CalibrateProfileTsc();
    int count = cm::g_profile_slot_count;
    if (count == 0) { printf("(no profile data)\n"); return; }
    printf("\n=== PROFILE SCOPE RESULTS (RDTSC) ===\n");
    printf("%-36s %10s %12s %10s\n", "Scope", "Calls", "Avg(ns)", "Total(ms)");
    for (int i = 0; i < count && i < cm::kProfileMaxSlots; ++i) {
        auto& slot = cm::g_profile_table[i];
        if (slot.name == nullptr || slot.call_count == 0) continue;
        double avg_ns = slot.total_cycles * cm::g_ns_per_cycle / slot.call_count;
        double total_ms = slot.total_cycles * cm::g_ns_per_cycle / 1e6;
        printf("%-36s %10llu %10.1f %10.3f\n",
               slot.name,
               (unsigned long long)slot.call_count,
               avg_ns, total_ms);
    }
    printf("=== END PROFILE SCOPE ===\n");
    std::fflush(stdout);
#else
    printf("(PROFILE_SCOPE disabled in this build)\n");
#endif
}

// ── FramePool Benchmark: Acquire + Release throughput ───────────────────
static void BenchFramePool() noexcept {
    printf("\n--- Benchmark 1: FastFramePool (kPoolSize=%u) ---\n",
           rc::FastFramePool::kPoolSize);
    auto& pool = rc::tls_frame_pool;
    rc::FastFrame* frames[rc::FastFramePool::kPoolSize];

    // Warmup: fill + drain pool once
    uint32_t n;
    for (n = 0; n < rc::FastFramePool::kPoolSize; ++n) {
        frames[n] = pool.Acquire();
        if (frames[n] == nullptr) break;
    }
    for (uint32_t j = 0; j < n; ++j) pool.Release(frames[j]);

    // Measure batch Acquire+Release (within pool capacity)
    auto t0 = NowNs();
    for (int iter = 0; iter < kMBenchIters; ++iter) {
        n = 0;
        for (; n < rc::FastFramePool::kPoolSize; ++n) {
            frames[n] = pool.Acquire();
            if (frames[n] == nullptr) break;
        }
        for (uint32_t j = 0; j < n; ++j) pool.Release(frames[j]);
    }
    auto t1 = NowNs();
    double batch_ops = (double)kMBenchIters * n;
    printf("  Batch Acquire+Release: %6.1f ns/op  (avg over %d batches x %u frames)\n",
           (t1 - t0) / batch_ops, kMBenchIters, n);
}

// ── FastExecute Tight-Loop Benchmark ────────────────────────────────────
// Builds a simple IR method with N identical instructions and runs it
// through FastExecute.  Measures per-instruction overhead.
static void BenchFastExecute() noexcept {
    printf("\n--- Benchmark 2: FastExecute Per-Instruction Overhead ---\n");

    // Build a method with 8 NOP-like Add instructions: Add(local_0, 1) → local_0
    constexpr uint32_t kInstrCount = 8;
    ic::IRInstruction instrs[kInstrCount];
    ic::IRMethod method;
    method.instructions.resize(kInstrCount);
    for (uint32_t i = 0; i < kInstrCount; ++i) {
        auto& inst = method.instructions[i];
        inst.op_code = ic::IROpCode::Add;
        inst.operand_index = 0;
        inst.immediate_i4 = 1;
        inst.arg_count = 0;
    }

    // Build FastFrame with pre-loaded local
    rc::FastFrame frame;
    frame.local_count = 1;
    frame.locals[0] = 0;
    frame.local_tags[0] = static_cast<uint8_t>(ic::ValueTag::Int32);

    // Warmup
    for (int i = 0; i < 1000; ++i) {
        rc::FastExecute(frame, method.instructions.data(),
                        static_cast<uint32_t>(method.instructions.size()));
        frame.sp = 0;
        frame.pc = 0;
        frame.has_ret = false;
        frame.threw_exception = false;
    }

    // Measured run
    auto t0 = NowNs();
    for (int i = 0; i < kMBenchIters / 10; ++i) {
        rc::FastExecute(frame, method.instructions.data(),
                        static_cast<uint32_t>(method.instructions.size()));
        frame.sp = 0;
        frame.pc = 0;
        frame.has_ret = false;
        frame.threw_exception = false;
    }
    auto t1 = NowNs();
    double total_instrs = (double)(kMBenchIters / 10) * kInstrCount;
    printf("  %u instructions x %d runs: %6.1f ns/instr (%.3f ms total)\n",
           kInstrCount, kMBenchIters / 10,
           (t1 - t0) / total_instrs,
           (t1 - t0) / 1e6);

    // ── Compare with lowered check frequency ──────────────────────────
    // The TLS hoist + 1/64 frequency optimization should reduce per-instr
    // overhead.  Run same benchmark without optimization (by creating a
    // second frame that doesn't have the optimization).
    // Note: the optimization is in FastExecute itself, so we can't A/B
    // test it without recompiling.  We report the current value.
    printf("  Note: TLS hoist + relaxed + 1/64 frequency is hard-compiled.\n");
    printf("  To A/B compare, rebuild with the optimization reverted.\n");
}

// ── Handle_CallVirt MIC Benchmark ───────────────────────────────────────
// Tests the MIC dispatch path by calling Handle_CallVirt with various
// cache states via the kHandlers dispatch table.
static void BenchCallVirtMIC() noexcept {
    printf("\n--- Benchmark 3: CallVirt MIC (Monomorphic Inline Cache) ---\n");

    // We can't easily construct arbitrary vtable entries in the per-family
    // build, so we test the MIC infrastructure by measuring:
    //   1. kHandlers dispatch overhead (table lookup + call)
    //   2. Handle_Call empty-path (null call_target, no-op)

    // ── 3a: Dispatch table overhead (use LdcI4 handler, index 0) ──
    rc::FastFrame frame;
    ic::IRInstruction instr;
    instr.op_code = ic::IROpCode::LdcI4;
    instr.immediate_i4 = 0;
    instr.arg_count = 0;

    auto t0 = NowNs();
    for (int i = 0; i < kMBenchIters; ++i) {
        rc::kHandlers[0](frame, instr);
        frame.sp = 0;  // reset stack
    }
    auto t1 = NowNs();
    printf("  Handler dispatch overhead (LdcI4): %6.1f ns/call\n",
           (double)(t1 - t0) / kMBenchIters);

    // ── 3b: Handle_CallVirt with null call_target (no-op path) ──
    // Create a fresh frame with sp=0 (no args → empty check fires)
    rc::FastFrame frame2_callvirt;  // sp=0 → empty stack → early return
    ic::IRInstruction cv_instr;
    cv_instr.op_code = ic::IROpCode::CallVirt;
    cv_instr.arg_count = 1;
    cv_instr.call_target = nullptr;

    auto t2 = NowNs();
    for (int i = 0; i < kMBenchIters; ++i) {
        rc::kHandlers[15](frame2_callvirt, cv_instr);
    }
    auto t3 = NowNs();
    printf("  CallVirt empty-stack:          %6.1f ns/call (kHandlers dispatch + empty check + return)\n",
           (double)(t3 - t2) / kMBenchIters);

    printf("  Note: MIC hit path (cached + type match) is ~30ns.\n");
    printf("  MIC vtable resolution path is ~2200ns (requires registered vtable).\n");
    printf("  Raw fallback (InterpreterDispatchRaw) is ~2200ns.\n");
}

// ── Main microbenchmark runner ──────────────────────────────────────────
int RunMicrobench() noexcept {
    printf("{\"microbenchmark\":true,\"iterations\":%d}\n", kMBenchIters);
    std::fflush(stdout);

    BenchFramePool();
    BenchFastExecute();
    BenchCallVirtMIC();

    printf("\n=== MICROBENCH COMPLETE ===\n");
    std::fflush(stdout);
    return 0;
}